from collections import deque

def find_conn_components(grid, component_id_grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    comp_id = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in visited:
                # BFS to find component
                comp = []
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and \
                           grid[nr][nc] == 0 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                # Store component
                for cr, cc in comp:
                    component_id_grid[cr][cc] = comp_id
                comp_id += 1

    return comp_id

